#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "create_runtime_float_layer.h"
int main(int argc,char**argv){try{if(argc!=2)return 1;SessionRuntime r(loadGraph(argv[1]));MutationCoordinator m;std::array<char,16> id{};id.fill(char(0x27));auto count=r.graph.elements.size();auto handle=createRuntimeFloatLayer(r,m,id,4);auto attr=r.attributes.find(handle,"values");auto identity=r.attributes.identity(r.graph,r.elements,attr);if(r.graph.elements.size()!=count+1||m.owners.at(handle).attributeFlags.at(identity)!=17)throw std::runtime_error("runtime layer registration mismatch");auto compressed=r.attributes.find(handle,"compressed");if(m.owners.at(handle).attributeFlags.at(r.attributes.identity(r.graph,r.elements,compressed))!=0x8006)throw std::runtime_error("compressed schema flags missing");
 r.graph.elements.reserve(r.graph.elements.capacity()+100);if(r.attributes.identity(r.graph,r.elements,attr)!=identity||!r.attributes.resolve(r.graph,r.elements,attr))throw std::runtime_error("identity invalidated by growth");validateGraph(r.graph);bool rejected=false;try{createRuntimeFloatLayer(r,m,id,4);}catch(const std::runtime_error&){rejected=true;}if(!rejected||r.graph.elements.size()!=count+1)throw std::runtime_error("duplicate UUID accepted");std::cout<<"runtime_float_layer_checks=4\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

